#!/usr/bin/env ruby
# frozen_string_literal: true

# Generates the site's pages, news and bibliography from the plain content files in
# ../website-content (bio.md, research.md, publications.bib, news.yml, teaching.yml,
# people.yml, grants-service-talks.yml, prospective-students.md, site-settings.yml).
#
# Usage, from the repository root:
#   ruby bin/build_content.rb [path/to/website-content]
#
# Edit the content files, not the generated files. Generated files are overwritten.

Encoding.default_external = Encoding::UTF_8
Encoding.default_internal = Encoding::UTF_8

require "yaml"
require "date"
require "fileutils"

ROOT = File.expand_path("..", __dir__)
SRC = File.expand_path(ARGV[0] || File.join(ROOT, "..", "website-content"))
abort("Content folder not found: #{SRC}") unless Dir.exist?(SRC)

def src(name) = File.join(SRC, name)
def out(name) = File.join(ROOT, name)
def yaml(name) = YAML.safe_load_file(src(name), permitted_classes: [Date])

GENERATED = "<!-- Generated by bin/build_content.rb from website-content. Edit the content files instead. -->"

def write(path, front_matter, body)
  FileUtils.mkdir_p(File.dirname(out(path)))
  File.write(out(path), "#{front_matter.to_yaml}---\n\n#{GENERATED}\n\n#{body.strip}\n")
end

# Section of a markdown file between "## heading" and the next "---" or "## " line.
def md_section(text, heading)
  lines = text.lines
  start = lines.index { |l| l.strip.start_with?("## #{heading}") } or abort("Missing section '#{heading}'")
  body = []
  lines[(start + 1)..].each do |l|
    break if l.start_with?("---", "## ")
    body << l
  end
  body.join.strip
end

def strip_html_comments(text) = text.gsub(/<!--.*?-->/m, "").strip

# ---------------------------------------------------------------------------
# Bibliography: copy publications.bib, mapping the content-only fields to the theme's.
# ---------------------------------------------------------------------------
PDFS = Dir.children(out("assets/pdf")).select { |f| f.end_with?(".pdf") }.map { |f| File.basename(f, ".pdf") }
# Official PDFs. ACM papers (DOI 10.1145/...) link to the ACM Digital Library PDF, since ACM has been
# fully open access since January 2026. Others link to the publisher's open PDF listed here.
# Self-published workshop papers and open-access articles with no stable PDF URL use the copy in
# assets/pdf/<key>.pdf. Paywalled papers (IEEE, Springer, ASCE) get no PDF link, only the DOI.
OFFICIAL_PDFS = {
  "li2023hcomp" => "https://ojs.aaai.org/index.php/HCOMP/article/view/27550/27323",
  "martin2026aies" => "https://ojs.aaai.org/index.php/AIES/article/view/43268/50828",
  "li2025nlp4dh" => "https://aclanthology.org/2025.nlp4dh-1.16.pdf",
  "ding2025jtrp" => "https://docs.lib.purdue.edu/cgi/viewcontent.cgi?article=3498&context=jtrp",
  "li2022hcompwip" => "https://www.humancomputation.com/2022/assets/wips_demos/HCOMP_2022_paper_5907.pdf",
  "li2025vibe" => "https://arxiv.org/pdf/2507.21012",
  "li2024digiage" => "https://arxiv.org/pdf/2603.08818",
  "li2024sensemaking" => "https://arxiv.org/pdf/2603.08604"
}.freeze

bib = File.read(src("publications.bib"))
bib = bib.gsub(/^(\s*)type(\s*)= \{(workshop|thesis)\},/) { "#{$1}category#{$2}= {#{$3}}," }
bib = bib.sub(/(@techreport\{ding2025jtrp,)/, "\\1\n  category    = {report},")
# PDFs live in assets/pdf/ named after the BibTeX key (e.g. li2018crowdia.pdf), so any
# file names in the content file are dropped and re-added from what is actually on disk.
bib = bib.gsub(/^\s*pdf\s*=\s*\{[^}]*\},\n/, "")
bib = bib.gsub(/^@(\w+)\{([^,]+),\n/) do
  type, key = $1, $2
  extra = +""
  entry_body = bib[/@\w+\{#{Regexp.escape(key)},(.*?)\n\}/m, 1].to_s
  doi = entry_body[/^\s*doi\s*=\s*\{([^}]*)\}/, 1]
  pdf = if doi&.start_with?("10.1145/") then "https://dl.acm.org/doi/pdf/#{doi}"
        elsif OFFICIAL_PDFS[key] then OFFICIAL_PDFS[key]
        elsif PDFS.include?(key) then "#{key}.pdf"
        end
  extra << "  pdf       = {#{pdf}},\n" if pdf
  extra << "  poster    = {#{key}-poster.png},\n" if File.exist?(out("assets/pdf/#{key}-poster.png"))
  "@#{type}{#{key},\n#{extra}"
end
# The public copy carries citation data only: content-file comments and internal working fields
# (verify, todo, category) stay in website-content/publications.bib and never reach the repository.
public_bib = bib.lines.reject { |l| l.start_with?("%") || l =~ /^\s*(verify|todo|category)\s*=/ }.join
public_bib = public_bib.gsub(/\n{3,}/, "\n\n").sub(/\A\s+/, "")
File.write(out("_bibliography/papers.bib"),
           "% Publications of Tianyi Li. Generated by bin/build_content.rb; edit the source file, not this one.\n\n#{public_bib}")

# ---------------------------------------------------------------------------
# Paper references: "{paper:key}" in content files becomes the linked title plus every author.
# ---------------------------------------------------------------------------
ACCENTS = { "'" => { "a" => "á", "e" => "é", "i" => "í", "o" => "ó", "u" => "ú" },
            "`" => { "a" => "à", "e" => "è" }, '"' => { "o" => "ö", "u" => "ü" } }.freeze
def clean_tex(s)
  s.to_s.gsub(/\{\\(['`"])\{?\\?([a-z])\}?\}/) { ACCENTS.dig($1, $2) || $2 }
       .gsub(/\\(['`"])\{?\\?([a-z])\}?/) { ACCENTS.dig($1, $2) || $2 }
       .gsub(/[{}]/, "").gsub("\\&", "&").gsub("``", "“").gsub("''", "”").strip
end

entries = {}
bib.scan(/^@\w+\{([^,]+),(.*?)\n\}/m) do |key, body|
  field = ->(f) { body[/^\s*#{f}\s*=\s*\{(.*)\},?\s*$/, 1] }
  authors = field.("author").to_s.split(" and ").map do |a|
    last, first = a.split(",", 2).map(&:strip)
    clean_tex(first ? "#{first} #{last}" : last)
  end
  entries[key] = { title: clean_tex(field.("title")), year: field.("year"), abbr: clean_tex(field.("abbr")),
                   doi: field.("doi"), html: field.("html"), authors: authors }
end

def join_names(names)
  return names.join(" and ") if names.size <= 2
  "#{names[0..-2].join(', ')}, and #{names.last}"
end

def paper_ref(entries, key)
  e = entries.fetch(key) { abort("Unknown paper key in content: #{key}") }
  link = e[:doi] ? "https://doi.org/#{e[:doi]}" : e[:html]
  title = link ? "[*#{e[:title]}*](#{link})" : "*#{e[:title]}*"
  "#{title} (#{join_names(e[:authors])})"
end

def expand_papers(text, entries) = text.gsub(/\{paper:([\w-]+)\}/) { paper_ref(entries, $1) }

# ---------------------------------------------------------------------------
# News
# ---------------------------------------------------------------------------
Dir.glob(out("_news/*.md")).each { |f| File.delete(f) }
yaml("news.yml").each_with_index do |item, i|
  date = Date.parse(item["date"].to_s)
  write("_news/#{date.iso8601}-#{format('%02d', i)}.md",
        { "layout" => "post", "date" => date.iso8601, "inline" => true, "related_posts" => false },
        expand_papers(item["text"], entries))
end

# ---------------------------------------------------------------------------
# Media (shown on the homepage)
# ---------------------------------------------------------------------------
# Media coverage is kept in grants-service-talks.yml but not shown on the site (removed Oct 14, 2026).

# ---------------------------------------------------------------------------
# About (home)
# ---------------------------------------------------------------------------
settings = yaml("site-settings.yml")
bio = File.read(src("bio.md"))
home_bio = md_section(bio, "Homepage bio")
thesis = md_section(bio, "Research one-liner")
join_text = if settings["recruiting"].to_s.strip.empty?
              "Interested in joining the lab? Please read the [prospective students](/prospective/) page."
            else
              "#{settings['recruiting'].strip} Please read the [prospective students](/prospective/) page."
            end
write("_pages/about.md", {
  "layout" => "about", "title" => "About", "permalink" => "/",
  "subtitle" => "Assistant Professor, <a href=\"https://polytechnic.purdue.edu/academic-areas/acc\">School of Applied and Creative Computing</a>, Purdue University · Director, Co-Intelligence Lab",
  "profile" => { "align" => "right", "image" => File.basename(settings["headshot"]), "image_circular" => true },
  "selected_papers" => false, "social" => false, "profile_social" => true,
  "announcements" => { "enabled" => true, "scrollable" => false, "limit" => 8 },
  "latest_posts" => { "enabled" => false }
}, <<~MD)
  <p class="thesis">#{thesis}</p>

  #{home_bio}

  <div class="join-box" markdown="1">
  #{join_text}
  </div>
MD

# ---------------------------------------------------------------------------
# Research (hidden until the themes are ready: show_research_page in site-settings.yml)
# ---------------------------------------------------------------------------
if settings["show_research_page"]
  research = File.read(src("research.md"))
  overview = md_section(research, "Overview (intro paragraph on the Research page)")
  themes = research.split(/^## (?=\d\. )/)[1..].map do |chunk|
    chunk = chunk.split(/^---/).first
    heading, *rest = chunk.lines
    text = rest.join.strip.lines.reject { |l| l.start_with?("- Funding:") }.join
    text = text.gsub(/^- Representative papers: (.*)$/) do
      refs = $1.scan(/\[(\w+)\]/).flatten.map { |k| "  - #{paper_ref(entries, k)}" }
      "- Representative papers:\n#{refs.join("\n")}"
    end
    "## #{heading.strip.sub(/^\d\.\s*/, '')}\n\n#{text}"
  end
  write("_pages/research.md", { "layout" => "page", "permalink" => "/research/", "title" => "Research",
                                "description" => "The Co-Intelligence Lab at Purdue University", "nav" => true, "nav_order" => 1 },
        "#{overview}\n\n#{themes.join("\n\n")}")
else
  FileUtils.rm_f(out("_pages/research.md"))
end

# ---------------------------------------------------------------------------
# Teaching: level, semesters taught, core topics
# ---------------------------------------------------------------------------
t = yaml("teaching.yml")
teaching_md = t["institutions"].map do |inst|
  courses = inst["courses"].map do |c|
    <<~MD
      ### #{c['code']}: #{c['title']}

      *#{c['level']} · #{c['terms'].reverse.join(', ')}*

      **Core topics:** #{c['topics'].strip}
    MD
  end
  "## #{inst['name']}\n\n#{courses.join("\n")}"
end
write("_pages/teaching.md", { "layout" => "page", "permalink" => "/teaching/", "title" => "Teaching",
                              "description" => "Courses taught", "nav" => true, "nav_order" => 3 }, teaching_md.join("\n"))

# ---------------------------------------------------------------------------
# Students: current and alumni, grouped by level
# ---------------------------------------------------------------------------
pp = yaml("people.yml")
cur = pp["current"]
alum = pp["alumni"]
person = ->(p) { p["note"] ? "- #{p['name']} (#{p['note']})" : "- #{p['name']}" }
current_groups = [["Ph.D. students", "phd"], ["Doctor of Technology students", "dtech"], ["M.S. students", "ms"],
                  ["Graduate research assistants", "research_assistants"], ["Undergraduate researchers", "undergraduates"]]
current_md = current_groups.filter_map do |label, k|
  next unless cur[k]&.any?
  "### #{label}\n\n#{cur[k].map(&person).join("\n")}"
end
degree_line = lambda do |a, degree|
  line = "- **#{a['name']}**, #{degree} #{a['year']}"
  # Thesis and dissertation titles are intentionally not shown.
  line += " (#{a['note']})" if a["note"]
  line
end
alumni_md = []
alumni_md << "### Ph.D.\n\n#{alum['phd'].map { |a| degree_line.(a, 'Ph.D.') }.join("\n")}" if alum["phd"]&.any?
alumni_md << "### M.S.\n\n#{alum['ms'].map { |a| degree_line.(a, 'M.S.') }.join("\n")}" if alum["ms"]&.any?
alumni_md << "### Graduate researchers\n\n#{alum['graduate_researchers'].map { |n| "- #{n}" }.join("\n")}" if alum["graduate_researchers"]&.any?
alumni_md << "### Undergraduate researchers\n\n#{alum['undergraduate_researchers'].map { |n| "- #{n}" }.join("\n")}" if alum["undergraduate_researchers"]&.any?

student_names = (cur.values.flatten.flat_map { |p| [p["name"], *p["aliases"].to_a] } + alum["phd"].to_a.map { |a| a["name"] } +
                 alum["ms"].to_a.map { |a| a["name"] } + alum["graduate_researchers"].to_a +
                 alum["undergraduate_researchers"].to_a).uniq
File.write(out("_data/students.yml"), "# Generated by bin/build_content.rb from website-content/people.yml.\n# Authors matching these names are marked as student advisees on publication lists.\n#{student_names.to_yaml}")
write("_pages/students.md", { "layout" => "page", "permalink" => "/students/", "title" => "Students",
                              "description" => "Members and alumni of the Co-Intelligence Lab", "nav" => true, "nav_order" => 4 }, <<~MD)
  I am fortunate to work with an excellent group of students who bring curiosity, care, and a wide range of backgrounds to our research. They lead much of the lab's work, from designing and building systems to studying how people use them in classrooms and communities, and many have presented their research at leading conferences in human–computer interaction and computing education.

  ## Current students

  #{current_md.join("\n\n")}

  ## Alumni

  #{alumni_md.join("\n\n")}
MD

FileUtils.rm_f(out("_pages/service.md")) # service page removed (Oct 14, 2026)

# CV page removed (Oct 14, 2026).
FileUtils.rm_f(out("_pages/cv.md"))

# ---------------------------------------------------------------------------
# Prospective students
# ---------------------------------------------------------------------------
pros = strip_html_comments(File.read(src("prospective-students.md"))).sub(/\A# .*\n+/, "")
write("_pages/prospective.md", { "layout" => "page", "permalink" => "/prospective/", "title" => "Prospective Students",
                                 "description" => "Joining the Co-Intelligence Lab", "nav" => true, "nav_order" => 7 },
      expand_papers(pros, entries))

puts "Generated pages, #{yaml('news.yml').size} news items, and _bibliography/papers.bib from #{SRC}"
